function pad2(n){ n=Math.floor(n); return (n<10?'0':'')+n; }
function fmt(sec){ sec=Math.max(0,Math.floor(sec)); return pad2(Math.floor(sec/60))+':'+pad2(sec%60); }
function buildPhases(workSec, breakSec, rounds){
  workSec=Math.max(1,Math.min(3600,(+workSec)||1200));
  breakSec=Math.max(1,Math.min(600,(+breakSec)||20));
  rounds=Math.max(1,Math.min(50,(+rounds)||8));
  var ph=[]; for(var i=0;i<rounds;i++){ ph.push({type:'work', sec:workSec}); ph.push({type:'break', sec:breakSec}); }
  return {phases:ph, workSec:workSec, breakSec:breakSec, rounds:rounds};
}
var EXPORTS={fmt:fmt, buildPhases:buildPhases};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RestReminderForgePure = EXPORTS; }
